HOURGLASS_ENV=test python3 -m unittest discover -s tests 2>&1 | tail -4; echo "---lint"; python3 tools/lint.py; echo "---line length >60"; awk 'length > 60 {print FILENAME": "FNR": "length}' hourglass/gaps.py tests/test_gaps.py; echo "---double blanks"; for f in hourglass/gaps.py tests/test_gaps.py; do awk -v f=$f 'prev=="" && $0=="" {print f": "FNR} {prev=$0}' $f; done; echo "---function sizes"; python3 -c "
import ast,sys
for path in ['hourglass/gaps.py','tests/test_gaps.py']:
    tree=ast.parse(open(path).read())
    for node in ast.walk(tree):
        if isinstance(node,ast.FunctionDef):
            size=node.end_lineno-node.lineno+1
            if node.body and node.body[0].col_offset==0: pass
            print(path,node.name,size)
"; echo "---ascii check of names"; grep -n "# ---" -A1 hourglass/gaps.py tests/test_gaps.py | head -20

HOURGLASS_ENV=test python3 -m unittest discover -s tests 2>&1 | tail -3; echo "---lint"; python3 tools/lint.py; echo "---line length >60"; awk 'length > 60 {print FILENAME": "FNR": "length}' hourglass/gaps.py tests/test_gaps.py; echo "---double blanks"; for f in hourglass/gaps.py tests/test_gaps.py; do awk -v f=$f 'prev=="" && $0=="" {print f": "FNR} {prev=$0}' $f; done; echo "---sizes"; python3 -c "
import ast
for path in ['hourglass/gaps.py','tests/test_gaps.py']:
    tree=ast.parse(open(path).read())
    for node in ast.walk(tree):
        if isinstance(node,ast.FunctionDef) and node.end_lineno-node.lineno+1>8: print('TOO LONG',path,node.name)
print('size check done')
"; echo "---names under 4 letters"; grep -nE "\b[a-z_]{1,3}\b *=|for [a-z_]{1,3} in|as [a-z]{1,3}\b" hourglass/gaps.py tests/test_gaps.py; echo "---imports"; head -8 hourglass/gaps.py; echo done

